function updateMartuSleep(dt){if(martuSleep.awake)return;const m=findMartuSleepStudent();if(!m)return;const leaf={x:1415,y:72,w:105,h:34};const feet={x:player.x+8,y:player.y+player.h-12,w:player.w-16,h:18};if(rect(feet,leaf)&&player.onGround){if(!martuSleep.touching){addMartuNoise(shoesOwned?1.5:1);martuSleep.touching=true;}}else martuSleep.touching=false;if(elapsed-martuSleep.lastNoiseAt>4)martuSleep.noise=Math.max(0,martuSleep.noise-dt*.06);}
