function updateRiverPhysics(dt){
  const inRiverX=player.x>=9666&&player.x<=11400;
  if(!inRiverX)return;

  // El agua ocupa la franja inferior. Si el Profe cae entre las piedras,
  // entra en corriente en lugar de caer al vacío.
  const waterTop=430;
  const waterBottom=610;

  if(player.y+player.h>=waterTop && player.y<waterBottom){
    // Corriente fuerte hacia la izquierda.
    player.vx-=780*dt;

    // Flotación: impedir caída infinita y mantenerlo cerca de la superficie.
    if(player.y>438){
      player.vy-=1450*dt;
    }

    // Tope inferior de seguridad.
    if(player.y>500){
      player.y=500;
      player.vy=-260;
    }

    // Sensación de resistencia.
    player.vx*=Math.pow(.90,dt*60);

    // No permitir que la corriente lo saque por debajo del mapa.
    if(player.y+player.h>560){
      player.y=560-player.h;
      player.vy=-220;
    }
  }
}
function updateRiverRescue(dt){
  if(riverRescue.rescued&&riverRescue.safeOnShore)return;

  // Si ya fue liberado, nada solo hasta la orilla.
  if(riverRescue.swimming){
    const dx=riverRescue.swimTargetX-riverRescue.x;
    const dy=riverRescue.swimTargetY-riverRescue.y;
    const dist=Math.hypot(dx,dy);

    if(dist>8){
      riverRescue.x+=dx*Math.min(1,dt*1.7);
      riverRescue.y+=dy*Math.min(1,dt*1.7);
      return;
    }

    riverRescue.x=riverRescue.swimTargetX;
    riverRescue.y=riverRescue.swimTargetY;
    riverRescue.swimming=false;
    riverRescue.safeOnShore=true;
    riverRescue.rescued=true;
    riverRescue.active=false;

    students++;
    followers.push({
      x:riverRescue.x,y:riverRescue.y,
      girl:false,glasses:false,name:"Monito del río",
      delay:followers.length*.18,
      vineState:"follow",vineLatchDelay:0
    });

    groupReaction={type:"hug",t:1.2};
    playStudent();
    return;
  }

  if(!riverRescue.active)return;

  const kidHit={x:riverRescue.x,y:riverRescue.y,w:riverRescue.w,h:riverRescue.h};

  // Llegar hasta él lo libera, pero NO hace que todos los followers entren.
  if(rect(player,kidHit)){
    riverRescue.swimming=true;
    riverRescue.active=true;
    groupReaction={type:"surprise",t:.8};
    return;
  }

  // Solución con pelota: la pelota lo impulsa fuera del palo.
  if(thrownBall&&rect({x:thrownBall.x,y:thrownBall.y,w:34,h:34},kidHit)){
    riverRescue.swimming=true;
    riverRescue.x+=120;
    riverRescue.y-=55;
    thrownBall.vx*=.45;
    thrownBall.vy=-120;
    groupReaction={type:"surprise",t:.8};
  }
}
function drawRiverRescue(){
  if(!riverRescue.active&&!riverRescue.swimming)return;

  const a=sx(riverRescue.x),b=sy(riverRescue.y);
  if(a<-80||a>W+80)return;

  ctx.save();

  // cuerpo del monito
  ctx.fillStyle="#7b4a24";
  ctx.beginPath();ctx.arc(a+20,b+20,17,0,Math.PI*2);ctx.fill();

  ctx.fillStyle="#b9824b";
  ctx.beginPath();ctx.arc(a+20,b+21,11,0,Math.PI*2);ctx.fill();

  ctx.fillStyle="#2b1a0e";
  ctx.beginPath();ctx.arc(a+16,b+18,2,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(a+24,b+18,2,0,Math.PI*2);ctx.fill();

  if(riverRescue.swimming){
    // Brazos/nado + salpicaduras.
    ctx.strokeStyle="#7b4a24";
    ctx.lineWidth=5;
    ctx.beginPath();
    ctx.moveTo(a+10,b+31);ctx.lineTo(a-4,b+22);
    ctx.moveTo(a+30,b+31);ctx.lineTo(a+44,b+24);
    ctx.stroke();

    ctx.strokeStyle="rgba(255,255,255,.8)";
    ctx.lineWidth=3;
    ctx.beginPath();
    ctx.arc(a-2,b+36,12,.2,2.4);
    ctx.arc(a+40,b+38,12,.7,2.9);
    ctx.stroke();
  }else{
    // agarrado del palo
    ctx.strokeStyle="#6b401f";
    ctx.lineWidth=5;
    ctx.beginPath();
    ctx.moveTo(a+29,b+30);
    ctx.lineTo(a+38,b-20);
    ctx.stroke();
  }

  ctx.restore();

  drawSpeechBubble(a+20,b-8,riverRescue.swimming?"🏊‍♂️💦":"😰🙏",.8);
}
