function spawnLifeDetails(dt){
  lifeClock += dt;

  // Hojas variadas: pocas, distintas, suaves.
  if(Math.random()<0.014){
    particles.push({
      x:camX+Math.random()*W,
      y:camY-25,
      vx:-10-Math.random()*35,
      vy:18+Math.random()*32,
      life:4+Math.random()*3,
      color:Math.random()>.5?"#5eb85a":"#7ccf62",
      type:"leaf",
      spin:Math.random()*6
    });
  }

  // Mariposas curiosas: no vuelan recto.
  if(Math.random()<0.003 && curiousButterflies.length<3){
    curiousButterflies.push({
      x:camX+W+40,
      y:camY+120+Math.random()*250,
      vx:-18-Math.random()*22,
      baseY:camY+120+Math.random()*250,
      life:10,
      phase:Math.random()*6
    });
  }

  // Pajaritos que se posan y salen volando si el profe se acerca.
  if(Math.random()<0.0025 && ambientBirds.length<3){
    const bx=camX+120+Math.random()*(W-240);
    const by=camY+95+Math.random()*150;
    ambientBirds.push({x:bx,y:by,vx:0,vy:0,life:12,scared:false});
  }
}

function updateLifeDetails(dt){
  curiousButterflies = curiousButterflies.filter(b=>b.life>0);
  for(const b of curiousButterflies){
    b.life-=dt;
    b.x+=b.vx*dt;
    b.y=b.baseY+Math.sin(elapsed*4+b.phase)*32+Math.sin(elapsed*9+b.phase)*7;
  }

  ambientBirds = ambientBirds.filter(b=>b.life>0);
  for(const b of ambientBirds){
    const dx=(player.x+player.w/2)-b.x;
    const dy=(player.y+player.h/2)-b.y;
    if(!b.scared && Math.abs(dx)<120 && Math.abs(dy)<120){
      b.scared=true;
      b.vx=dx<0?90:-90;
      b.vy=-95;
      msg("🐦",650);
    }
    if(b.scared){
      b.x+=b.vx*dt;
      b.y+=b.vy*dt;
      b.vy+=20*dt;
    }else{
      b.y+=Math.sin(elapsed*3+b.x)*6*dt;
    }
    b.life-=dt;
  }
}

function drawLifeDetails(){
  // Mariposas
  for(const b of curiousButterflies){
    const a=sx(b.x), c=sy(b.y);
    if(!drawAsset("butterflyLife",a,c,34,28)){
      ctx.fillStyle="#f08ad8";ctx.font="18px Arial";ctx.fillText("🦋",a,c);
    }
  }
  // Pajaritos
  for(const bird of ambientBirds){
    const a=sx(bird.x), c=sy(bird.y);
    ctx.save();
    if(bird.vx<0){ctx.translate(a+34,c);ctx.scale(-1,1);drawAsset("birdLife",0,0,34,26);}
    else drawAsset("birdLife",a,c,34,26);
    ctx.restore();
  }
}

function updateParticles(dt){
  if(Math.random()<0.018){
    particles.push({x:camX+Math.random()*W,y:camY-20,vx:-15-Math.random()*25,vy:20+Math.random()*18,life:4+Math.random()*2,color:"#5eb85a",type:"leaf"});
  }
  if(Math.random()<0.004){
    particles.push({x:camX+W+30,y:camY+80+Math.random()*220,vx:-25-Math.random()*20,vy:0,life:8,color:"#f08ad8",type:"butterflyTiny",baseY:camY+80+Math.random()*220});
  }
  particles=particles.filter(p=>p.life>0);
  for(const p of particles){
    p.life-=dt;
    if(p.type==="butterfly"){p.x+=p.vx*dt;p.y=p.baseY+Math.sin(elapsed*5)*18;}
    else if(p.type==="leaf"){p.x+=p.vx*dt+Math.sin(elapsed*4+p.x)*12*dt;p.y+=p.vy*dt;}
    else if(p.type==="butterflyTiny"){p.x+=p.vx*dt;p.y+=Math.sin(elapsed*5+p.x)*18*dt;}
    else if(p.type==="musicNote"){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=15*dt;}
    else{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;}
  }
}

function updateMusicRequests(dt){
  if(player.onVine||followers.some(f=>f.onVine||f.vineState==="climb"))return;
  for(const stop of musicStops){if(stop.done)continue;if(!stop.active&&instrumentOwned&&followers.length>=2&&player.x>stop.x-70&&player.x<stop.x+150){stop.active=true;groupReaction={type:"request",t:999};}}
}

function activeMusicStop(){
  return musicStops.find(s=>s.active&&!s.done)||null;
}

function updateGroupReactions(dt){
  if(groupReaction.t>0 && groupReaction.t<900){
    groupReaction.t=Math.max(0,groupReaction.t-dt);
    if(groupReaction.t===0)groupReaction.type=null;
  }

  // Reacción ocasional a salto alto.
  if(!player.onGround&&player.vy<-530&&elapsed-lastHighJumpReaction>2.4){
    lastHighJumpReaction=elapsed;
    groupReaction={type:Math.random()>.5?"surprise":"fun",t:.85};
  }
}

function drawMusicRequestBubble(){
  const stop=activeMusicStop();
  if(!stop||!followers.length||player.onVine||followers.some(f=>f.onVine))return;
  const f=followers[Math.min(1,followers.length-1)];
  drawSpeechBubble(sx(f.x+22),sy(f.y-18),"🎵🙏",.92);
}

function drawGroupReactionBubbles(){
  if(!groupReaction.type||!followers.length)return;
  if(groupReaction.type==="request")return;
  const symbols={hug:"🤗❤️",item:"🙌✨",music:"🎵😄",surprise:"😲",fun:"😄",noise:"🍂❗"};
  const txt=symbols[groupReaction.type]||"✨";
  const count=Math.min(3,followers.length);
  const seed=Math.abs(Math.floor(elapsed*31)+(groupReaction.type.length*17));
  const used=new Set();

  for(let i=0;i<count;i++){
    let idx=(seed+i*7)%followers.length,guard=0;
    while(used.has(idx)&&guard<followers.length){idx=(idx+1)%followers.length;guard++;}
    used.add(idx);
    const f=followers[idx];
    drawSpeechBubble(sx(f.x+22),sy(f.y-20-i*4),txt,.72);
  }
}

function updateFollowers(dt){
  const activeVine=player.onVine?findVine():null;

  const requestStop=activeMusicStop();
  const riverShoreHold=(player.x>9666&&player.x<11400);
  followers.forEach((f,i)=>{
    if(f.vineState===undefined)f.vineState="follow";
    if(f.vineLatchDelay===undefined)f.vineLatchDelay=0;

    if(activeVine){
      const vineCenterX=activeVine.x+activeVine.w/2;
      const vineTop=activeVine.y+8;
      const vineBottom=activeVine.y+activeVine.h-46;
      const delay=i*.09;

      f.vineLatchDelay+=dt;

      if(f.vineState!=="climb"){
        // Llegan al pie de la liana desde su posición real.
        const approachX=vineCenterX-21;
        const approachY=vineBottom;
        f.x+=(approachX-f.x)*Math.min(1,dt*8);
        f.y+=(approachY-f.y)*Math.min(1,dt*8);
        f.face=approachX>f.x?1:-1;

        if(Math.abs(f.x-approachX)<20 &&
           Math.abs(f.y-approachY)<38 &&
           f.vineLatchDelay>=delay){
          f.vineState="climb";
          f.onVine=true;
        }
        return;
      }

      f.onVine=true;

      // Repartir todo el grupo ENTRE el Profe y el final inferior de la liana.
      // Así nunca se teletransportan a la derecha ni quedan debajo del mapa.
      const remaining=Math.max(28,vineBottom-(player.y+player.h*.45));
      const packedSpacing=Math.max(18,Math.min(36,remaining/Math.max(1,followers.length)));
      const desiredY=player.y+player.h*.42+(i+1)*packedSpacing;
      const targetY=Math.max(vineTop,Math.min(vineBottom,desiredY));
      const targetX=vineCenterX-21;

      f.x+=(targetX-f.x)*Math.min(1,dt*12);
      f.y+=(targetY-f.y)*Math.min(1,dt*11);
      f.face=player.facing;
      return;
    }

    f.onVine=false;
    f.vineState="follow";
    f.vineLatchDelay=0;

    if(riverShoreHold){
      const targetX=9585-(i%4)*32;
      const targetY=392+(i%3)*7;
      f.x+=(targetX-f.x)*.06;
      f.y+=(targetY-f.y)*.08;
      f.face=1;
      return;
    }

    if(requestStop){
      const row=i%3;
      const col=Math.floor(i/3);
      const targetX=requestStop.x-65-col*34+row*26;
      const targetY=player.y+28+row*7;
      f.x+=(targetX-f.x)*.055;
      f.y+=(targetY-f.y)*.06;
      f.face=1;
      return;
    }

    const gap=62+i*38;
    const rowOffset=(i%2)*8;
    const targetX=player.x-(player.facing>=0?gap:-gap);
    const danceHop=radioDanceTimer>0?Math.sin(elapsed*13+i)*8:0;
    const targetY=player.y+32+rowOffset+Math.sin(elapsed*3+i)*4-danceHop;
    f.x+=(targetX-f.x)*.032;
    f.y+=(targetY-f.y)*.052;
    f.face=targetX>f.x?1:-1;
  });
}

