function drawSpeechBubble(x,y,text,scale=1){
  ctx.save();
  ctx.font=`900 ${Math.round(20*scale)}px Arial`;
  const pad=10*scale;
  const tw=ctx.measureText(text).width;
  const bw=tw+pad*2, bh=34*scale;
  ctx.fillStyle="rgba(255,255,255,.94)";
  ctx.strokeStyle="rgba(50,35,22,.72)";
  ctx.lineWidth=2;
  ctx.beginPath();
  ctx.roundRect(x-bw/2,y-bh,bw,bh,10*scale);
  ctx.fill();ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x-7*scale,y);
  ctx.lineTo(x+7*scale,y);
  ctx.lineTo(x,y+9*scale);
  ctx.closePath();ctx.fill();ctx.stroke();
  ctx.fillStyle="#2c1b10";
  ctx.textAlign="center";
  ctx.textBaseline="middle";
  ctx.fillText(text,x,y-bh/2);
  ctx.restore();
}

function drawCleanSign(type,a,b,w,h){
  ctx.save();

  // Poste
  const postW=Math.max(8,w*.08);
  ctx.fillStyle="#6d421f";
  ctx.fillRect(a+w*.48,b+h*.62,postW,h*.48);
  ctx.fillStyle="#916033";
  ctx.fillRect(a+w*.48+postW*.18,b+h*.62,postW*.28,h*.48);

  // Tabla simple, sin texto "horneado" debajo.
  const boardY=b+h*.12;
  const boardH=h*.58;
  ctx.fillStyle="#5a3418";
  ctx.fillRect(a-3,boardY-3,w+6,boardH+6);
  ctx.fillStyle="#e9c77d";
  ctx.fillRect(a,boardY,w,boardH);

  // Bordes pixel/cartoon.
  ctx.fillStyle="#f6dda2";
  ctx.fillRect(a+5,boardY+5,w-10,4);
  ctx.fillStyle="#b17b39";
  ctx.fillRect(a+5,boardY+boardH-8,w-10,4);

  drawSignLabel(type,a,boardY,w,boardH);
  ctx.restore();
}

function drawSignLabel(type,a,b,w,h){
  ctx.save();
  ctx.fillStyle="#3b2514";
  ctx.textAlign="center";
  ctx.textBaseline="middle";
  ctx.font="900 13px Arial";
  let lines=[];
  if(type==="welcomeSign"){ lines=["Selva del","Gran Árbol"]; ctx.font="900 15px Arial"; }
  if(type==="routeSign"){ lines=["Ruta Alta ↑","Túnel ↓"]; ctx.font="900 12px Arial"; }
  if(type==="tunnelSign"){ lines=["Túnel de","las Raíces"]; ctx.font="900 11px Arial"; }
  if(type==="treeSign"){ lines=["GRAN","ÁRBOL"]; ctx.font="900 16px Arial"; }
  if(type==="schoolSign"){ lines=["Escuela del","Gran Árbol →"]; ctx.font="900 15px Arial"; }
  if(type==="branchRouteSign"){ lines=["Ruta de","Ramas →"]; ctx.font="900 12px Arial"; }
  if(type==="adrenalineSign"){ lines=["Gran","Salto ↑"]; ctx.font="900 14px Arial"; }
  const step= type==="schoolSign" ? 17 : (type==="welcomeSign" ? 16 : 15);
  const cy=b+h*.50-(lines.length-1)*step/2;
  ctx.lineJoin="round";
  ctx.strokeStyle="rgba(255,241,207,.75)";
  ctx.lineWidth=2.2;
  for(let i=0;i<lines.length;i++){
    ctx.strokeText(lines[i],a+w/2,cy+i*step);
    ctx.fillText(lines[i],a+w/2,cy+i*step);
  }
  ctx.restore();
}

function drawItems(){
  // Engine 1.1: las lianas se dibujan primero y con margen enorme.
  for(const o of items){
    if(o.taken || o.type!=="vine")continue;
    let a=sx(o.x),b=sy(o.y);
    if(a<-1200||a>W+1200||b<-1800||b>H+1800)continue;
    vine(a,b,o.h,o.bob);
  }

  for(const o of items){
    if(o.taken || o.fled || o.type==="vine")continue;
    let a=sx(o.x),b=sy(o.y);
    if(a<-900||a>W+900||b<-1200||b>H+1200)continue;

    const bob=Math.sin(elapsed*2.2+o.bob)*4;
    if(["banana","golden","apple","orange","student","rock","humming","radio","ukulele","trumpet","battery"].includes(o.type)){
      drawShadow(a+o.w/2,b+o.h+4,Math.max(10,o.w*.45));
    }
    if(o.type==="banana")banana(a,b+bob,false);
    if(o.type==="golden")banana(a,b+bob,true);
    if(o.type==="apple")apple(a,b+bob);
    if(o.type==="orange")orange(a,b+bob);
    if(o.type==="student"){
      const questDance=o.lockedRadio&&radioQuestReleaseTimer>0;
      const sad=o.lockedRadio&&!radioQuestSolved;
      const musicDance=o.musicDistracted&&o.musicReactTimer>0;
      const distracted=o.musicDistracted&&!musicDance;
      const extraHop=(questDance||musicDance)?Math.sin(elapsed*12+o.bob)*7:0;

      student(a,b+Math.sin(elapsed*1.6+o.bob)*2-extraHop,o.girl,o.glasses,{
        sad,
        dance:questDance||musicDance,
        distracted
      });

      if(distracted){
        ctx.save();
        ctx.globalAlpha=.92;
        const sway=Math.sin(elapsed*2.2+o.bob);
        if(o.distraction==="butterfly"){
          ctx.font="18px Arial";ctx.fillText("🦋",a+48+sway*18,b-8+Math.sin(elapsed*4)*9);
        }else if(o.distraction==="hedgehog"){
          ctx.font="18px Arial";ctx.fillText("🦔",a+50+sway*14,b+40);
        }else{
          ctx.font="17px Arial";ctx.fillText("🐦",a+48+sway*22,b-5+Math.cos(elapsed*3)*7);
        }
        // El monito acompaña con la mirada/cuerpo.
        ctx.globalAlpha=.35;
        ctx.font="15px Arial";ctx.fillText("👀",a+15+sway*3,b+5);
        ctx.restore();
      }
    }
    if(o.type==="rock")rock(a,b,o.hit);
    if(o.type==="radio")radio(a,b,o.played);
    if(o.type==="ukulele")ukuleleItem(a,b,o.played);
    if(o.type==="trumpet")trumpetItem(a,b,o.played);
    if(o.type==="humming")humming(a,b+Math.sin(elapsed*5)*8);
    if(o.type==="battery")batteryItem(a,b+bob);
    if(o.type==="school")school(a,b);
  }
}


