  if(importantItemType==="ball"){ctx.font="30px Arial";ctx.fillText("⚽",itemX+6,itemY+28);}
  if(importantItemType==="branch"){ctx.fillStyle="#6b401f";ctx.fillRect(itemX-8,itemY+5,72,14);}
  if(importantItemType==="shoes"){ctx.font="30px Arial";ctx.fillText("👟",itemX+6,itemY+28);}

