function teleportTo(x,y){
  if(!Number.isFinite(x)||!Number.isFinite(y))return;
  player.x=x;player.y=y;player.vx=0;player.vy=0;player.onVine=false;
  player.spawnX=x;player.spawnY=y;
  camX=Math.max(0,x-W*.4);
  camY=y-H*.66;
}

function openTeleportPanel(){
  const panel=document.getElementById("teleportPanel");
  const input=document.getElementById("teleportInput");
  if(!panel||!input)return;
  panel.style.display="flex";
  input.value="";
  input.focus();
  input.select();
}

function closeTeleportPanel(){
  const panel=document.getElementById("teleportPanel");
  if(panel)panel.style.display="none";
}

function setupTeleportPanel(){
  const panel=document.getElementById("teleportPanel");
  const input=document.getElementById("teleportInput");
  if(!panel||!input)return;

  input.addEventListener("keydown",e=>{
    if(e.code==="ArrowDown"){
      e.preventDefault();
      input.value=`${Math.round(player.x)},${Math.round(player.y)}`;
      return;
    }
    if(e.code==="ArrowUp"){
      e.preventDefault();
      input.value=`${Math.round(lastTeleportTarget.x)},${Math.round(lastTeleportTarget.y)}`;
      return;
    }
    if(e.code==="Escape"){
      e.preventDefault();closeTeleportPanel();return;
    }
    if(e.code==="Enter"){
      e.preventDefault();
      const parts=input.value.trim().split(/[,\\s;]+/).map(Number);
      if(parts.length>=2&&Number.isFinite(parts[0])&&Number.isFinite(parts[1])){
        lastTeleportTarget={x:parts[0],y:parts[1]};
        teleportTo(parts[0],parts[1]);
        closeTeleportPanel();
      }else playNope();
    }
  });
}

setupTeleportPanel();
(function(){const u=document.getElementById("useCircle");if(u){u.style.pointerEvents="auto";u.addEventListener("click",e=>{e.preventDefault();cycleHeldItem();});}})();

window.addEventListener("keydown",e=>{
  if(e.code==="F1"){debugCoordinates=!debugCoordinates;e.preventDefault();return;}
  if(e.code==="F2"){e.preventDefault();if(!e.repeat)openTeleportPanel();return;}
  if(e.code==="KeyS"){e.preventDefault();musicHold=true;return;}
  if(e.code==="KeyD"){e.preventDefault();if(!e.repeat)useHeldItem();return;}
  if(e.code==="KeyF"){e.preventDefault();if(!e.repeat)cycleHeldItem();return;}
  if(e.code==="ArrowLeft")keys.left=true;if(e.code==="ArrowRight")keys.right=true;
  if(e.code==="KeyA"||e.code==="Space"||e.code==="ArrowUp")keys.jump=true;
  if(e.code==="ArrowDown")keys.down=true;
  if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Space","KeyA","KeyS","KeyD","KeyF"].includes(e.code))e.preventDefault();
});
window.addEventListener("keyup",e=>{if(e.code==="ArrowLeft")keys.left=false;if(e.code==="ArrowRight")keys.right=false;if(e.code==="KeyA"||e.code==="Space"||e.code==="ArrowUp")keys.jump=false;if(e.code==="ArrowDown")keys.down=false;if(e.code==="KeyS")musicHold=false;});
function bind(id,k){
  const e=document.getElementById(id);
  // Los botones inferiores ya no existen en esta versión.
  if(!e) return;
  const down=ev=>{
    ev.preventDefault();
    ev.stopPropagation();
    keys[k]=true;
    e.classList.add("pressed");
    softVibrate(12);
    try{ e.setPointerCapture(ev.pointerId); }catch(_){}
  };
  const up=ev=>{
    ev.preventDefault();
    ev.stopPropagation();
    keys[k]=false;
    e.classList.remove("pressed");
    try{ e.releasePointerCapture(ev.pointerId); }catch(_){}
  };
  e.addEventListener("pointerdown",down,{passive:false});
  e.addEventListener("pointerup",up,{passive:false});
  e.addEventListener("pointerleave",up,{passive:false});
  e.addEventListener("pointercancel",up,{passive:false});
  e.addEventListener("touchstart",ev=>ev.preventDefault(),{passive:false});
  e.addEventListener("touchmove",ev=>ev.preventDefault(),{passive:false});
}
bind("leftBtn","left");bind("rightBtn","right");bind("jumpBtn","jump");bind("downBtn","down");

// Beta 0.91: bloqueo extra de gestos molestos en móvil.
document.body.addEventListener("touchmove", e => {
  if(e.target.closest(".mobileControls") || e.target.tagName === "CANVAS") e.preventDefault();
}, {passive:false});
document.addEventListener("visibilitychange", ()=>{ if(document.hidden){ keys.left=false; keys.right=false; keys.jump=false; keys.down=false; document.querySelectorAll(".controlBtn").forEach(b=>b.classList.remove("pressed")); }});
window.addEventListener("blur", ()=>{
  keys.left=false; keys.right=false; keys.jump=false; keys.down=false;
  document.querySelectorAll(".controlBtn").forEach(b=>b.classList.remove("pressed"));
});


function goFullscreen(){
  const el=document.documentElement;
  if(el.requestFullscreen) el.requestFullscreen().catch(()=>{});
  else if(el.webkitRequestFullscreen) el.webkitRequestFullscreen();
}
function softVibrate(ms=18){
  if(navigator.vibrate) navigator.vibrate(ms);
}

buildLevel();draw();

// =========================================================
// CONTROLES TÁCTILES — joystick virtual superpuesto
// =========================================================
(function setupVirtualControls(){
  const stick=document.getElementById("virtualStick"),knob=document.getElementById("stickKnob"),music=document.getElementById("mobileMusic"),use=document.getElementById("mobileUse");
  if(!stick||!knob||!music||!use)return;let pid=null;const radius=36;
  function move(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy;const len=Math.hypot(dx,dy)||1;if(len>radius){dx=dx/len*radius;dy=dy/len*radius;}knob.style.transform=`translate(${dx}px,${dy}px)`;const dead=11;keys.left=dx<-dead;keys.right=dx>dead;keys.down=dy>18;keys.jump=dy<-18;}
  function release(){pid=null;knob.style.transform="translate(0,0)";keys.left=keys.right=keys.down=keys.jump=false;}
  stick.addEventListener("pointerdown",e=>{pid=e.pointerId;stick.setPointerCapture(e.pointerId);move(e);e.preventDefault();});
  stick.addEventListener("pointermove",e=>{if(e.pointerId===pid){move(e);e.preventDefault();}});stick.addEventListener("pointerup",e=>{if(e.pointerId===pid)release();e.preventDefault();});stick.addEventListener("pointercancel",release);
  music.addEventListener("pointerdown",e=>{musicHold=true;e.preventDefault();});const sm=e=>{musicHold=false;if(e)e.preventDefault();};music.addEventListener("pointerup",sm);music.addEventListener("pointercancel",sm);music.addEventListener("pointerleave",e=>{if(e.buttons===0)sm(e);});
  use.addEventListener("pointerdown",e=>{e.preventDefault();useHeldItem();softVibrate(12);});
})();;

